function depositAndStake(
    IERC20 _token,
    uint256 _amount,
    bytes calldata _collateralizableDepositApprovalSignature
) external withEligibleAccountTokensReleased(msg.sender, address(_token)) returns (uint256) {
    try
        collateral.depositFromAccount(
            msg.sender,
            address(_token),
            _amount,
            _collateralizableDepositApprovalSignature
        )
    {} catch (bytes memory reason) {
        if (bytes4(reason) != ICollateral.InvalidSignature.selector) {
            // Revert with the original error message
            assembly ("memory-safe") {
                revert(add(reason, 0x20), mload(reason))
            }
        }
        // If it reverts for signature reasons, we do not want to let the transaction revert [yet].
    }

    return _stake(_token, _amount);
}

function stake(
    IERC20 _token,
    uint256 _amount,
    bytes calldata _collateralizableApprovalSignature
) external withEligibleAccountTokensReleased(msg.sender, address(_token)) returns (uint256) {
    if (_collateralizableApprovalSignature.length > 0) {
        _tryModifyCollateralizableAllowanceWithSignature(
            address(_token),
            Pricing.safeCastToInt256(_amount),
            _collateralizableApprovalSignature
        );
    }

    return _stake(_token, _amount);
}

/**
 * @inheritdoc ITimeBasedCollateralPool
 */
function stakeReleasableTokensFrom(
    ITimeBasedCollateralPool _pool,
    IERC20 _token,
    uint256 _amount,
    bytes calldata _collateralizableApprovalSignature
) external withEligibleAccountTokensReleased(msg.sender, address(_token)) returns (uint256) {
    if (address(_pool) != address(this)) {
        IERC20[] memory tokens = new IERC20[](1);
        tokens[0] = _token;
        _pool.releaseEligibleTokens(msg.sender, tokens);
    }
    if (_collateralizableApprovalSignature.length > 0) {
        _tryModifyCollateralizableAllowanceWithSignature(
            address(_token),
            Pricing.safeCastToInt256(_amount),
            _collateralizableApprovalSignature
        );
    }

    return _stake(_token, _amount);
}

function _releaseEligibleAccountTokens(
    address _account,
    address _tokenAddress
) internal returns (bool _accountWasReset) {
    _accountWasReset = _unlockEligibleTokenContractPendingUnstakes(_tokenAddress);

    (uint256 totalUnitsToRelease, uint256 totalTokensToRelease) = _resetAccountTokenStateIfApplicable(
        _account,
        _tokenAddress
    );

    if (totalUnitsToRelease == 0) {
        (uint256 units, uint256 tokens) = _processAccountTokenUnstakes(_account, _tokenAddress);
        totalUnitsToRelease += units;
        totalTokensToRelease += tokens;
    } else {
        _accountWasReset = true;
    }

    if (totalUnitsToRelease == 0) {
        return _accountWasReset;
    }

    collateral.transferCollateral(_tokenAddress, totalTokensToRelease, _account);

    emit CollateralReleased(IERC20(_tokenAddress), totalTokensToRelease, totalUnitsToRelease, _account);

function _stake(IERC20 _token, uint256 _amount) internal returns (uint256 _poolUnitsIssued) {
    if (_amount == 0) revert InvalidZeroAmount();

    collateral.poolCollateral(msg.sender, address(_token), _amount);

    uint96 reservationId = tokenContractState[address(_token)].collateralReservationId;
    uint256 poolTotalUnitsAfter;
    uint256 poolTotalTokensAfter;
    if (reservationId == 0) {
        _poolUnitsIssued = _amount;
        (reservationId, ) = collateral.reserveCollateral(address(this), address(_token), _amount);
        tokenContractState[address(_token)].collateralReservationId = reservationId;
        tokenContractState[address(_token)].totalUnits = _poolUnitsIssued;
        accountTokenState[msg.sender][address(_token)].totalUnits = _poolUnitsIssued;

        poolTotalUnitsAfter = _poolUnitsIssued;
        poolTotalTokensAfter = _amount;
    } else {
        (poolTotalTokensAfter, ) = collateral.modifyCollateralReservation(
            reservationId,
            Pricing.safeCastToInt256(_amount)
        );
        uint256 poolUnits = tokenContractState[address(_token)].totalUnits;
        _poolUnitsIssued = Pricing.calculateProportionOfTotal(_amount, poolTotalTokensAfter - _amount, poolUnits);

        poolTotalUnitsAfter = poolUnits + _poolUnitsIssued;

        tokenContractState[address(_token)].totalUnits = poolTotalUnitsAfter;
        accountTokenState[msg.sender][address(_token)].totalUnits += _poolUnitsIssued;
    }

    {
        uint256 product;
        unchecked {
            product = (poolTotalTokensAfter * poolTotalUnitsAfter) / poolTotalUnitsAfter;
        }
        // This means that the contract will not be able to process withdrawals without overflowing, so must revert.
        // This can happen because the pool is empty, but the number of tokens being deposited is > 2**128 - 1
        // or if pool units have been diluted enough to make the units issued for this deposit very large.
        // If the latter, the pool should be reset.
        if (product != poolTotalTokensAfter) revert DepositTooLarge();
    }

    emit CollateralStaked(msg.sender, _token, _amount, _poolUnitsIssued);
}

function _tryModifyCollateralizableAllowanceWithSignature(
    address _collateralTokenAddress,
    int256 _collateralTokenAmount,
    bytes calldata _collateralizableAllowanceSignature
) private {
    try
        collateral.modifyCollateralizableTokenAllowanceWithSignature(
            msg.sender,
            address(this),
            _collateralTokenAddress,
            _collateralTokenAmount,
            _collateralizableAllowanceSignature
        )
    {} catch (bytes memory reason) {
        if (bytes4(reason) != ICollateral.InvalidSignature.selector) {
            // Revert with the original error message
            assembly ("memory-safe") {
                revert(add(reason, 0x20), mload(reason))
            }
        }
        // If it reverts for signature reasons, we do not want to let the transaction revert [yet].
    }
}

function depositFromAccount(
    address _accountAddress,
    address _tokenAddress,
    uint256 _amount,
    bytes calldata _collateralizableDepositApprovalSignature
) external {
    if (!collateralizableContracts[msg.sender]) revert Unauthorized(msg.sender);

    _verifyDepositApprovalSignature(
        _accountAddress,
        _tokenAddress,
        _amount,
        _collateralizableDepositApprovalSignature
    );

    uint256 allowance = accountCollateralizableTokenAllowances[_accountAddress][msg.sender][_tokenAddress];
    if (allowance < _amount) {
        _authorizedModifyCollateralizableTokenAllowance(
            _accountAddress,
            msg.sender,
            _tokenAddress,
            int256(_amount - allowance)
        );
    }

    _deposit(_accountAddress, _accountAddress, _tokenAddress, _amount);
}

function poolCollateral(
    address _accountAddress,
    address _tokenAddress,
    uint256 _amount
) external onlyEnabledCollateralTokens(_tokenAddress) {
    _requireCollateralizableAndDecreaseApprovedAmount(msg.sender, _accountAddress, _tokenAddress, _amount);

    _transferCollateral(_tokenAddress, _accountAddress, _amount, msg.sender);
}

function transferCollateral(address _tokenAddress, uint256 _amount, address _destinationAddress) external {
    _transferCollateral(_tokenAddress, msg.sender, _amount, _destinationAddress);
}

function _deposit(
    address _transferSource,
    address _accountAddress,
    address _tokenAddress,
    uint256 _amount
) internal onlyEnabledCollateralTokens(_tokenAddress) {
    CollateralToken storage collateralTokenStorage = collateralTokens[_tokenAddress];

    CollateralBalance storage accountBalanceStorage = accountBalances[_accountAddress][_tokenAddress];
    uint256 available = accountBalanceStorage.available;
    accountBalanceStorage.available = available + _amount;
    collateralTokenStorage.cumulativeUserBalance += _amount;

    IERC20(_tokenAddress).safeTransferFrom(_transferSource, address(this), _amount);

    emit FundsDeposited(_transferSource, _accountAddress, _tokenAddress, _amount);
}

function _requireCollateralizableAndDecreaseApprovedAmount(
    address _collateralizableAddress,
    address _accountAddress,
    address _tokenAddress,
    uint256 _amount
) internal {
    if (_collateralizableAddress == _accountAddress) {
        return;
    }
    if (!collateralizableContracts[_collateralizableAddress])
        revert ContractNotApprovedByProtocol(_collateralizableAddress);

    uint256 approvedAmount = accountCollateralizableTokenAllowances[_accountAddress][_collateralizableAddress][
        _tokenAddress
    ];
    if (approvedAmount < _amount)
        revert InsufficientAllowance(
            _collateralizableAddress,
            _accountAddress,
            _tokenAddress,
            _amount,
            approvedAmount
        );

    accountCollateralizableTokenAllowances[_accountAddress][_collateralizableAddress][_tokenAddress] =
        approvedAmount -
        _amount;
}

function _reserveCollateral(
    address _reservingContract,
    address _accountAddress,
    address _tokenAddress,
    uint256 _reservedCollateral,
    uint256 _claimableCollateral
) private onlyEnabledCollateralTokens(_tokenAddress) returns (uint96 _reservationId) {
    if (_claimableCollateral == 0) revert ClaimableAmountZero();

    _requireCollateralizableAndDecreaseApprovedAmount(
        _reservingContract,
        _accountAddress,
        _tokenAddress,
        _reservedCollateral
    );

    CollateralBalance storage accountBalanceStorage = accountBalances[_accountAddress][_tokenAddress];
    uint256 available = accountBalanceStorage.available;
    if (available < _reservedCollateral) revert InsufficientCollateral(_reservedCollateral, available);
    // sanity check -- this can never happen.
    if (_reservedCollateral < _claimableCollateral)
        revert InsufficientCollateral(_claimableCollateral, _reservedCollateral);

    accountBalanceStorage.available = available - _reservedCollateral;
    accountBalanceStorage.reserved += _reservedCollateral;

    uint16 withdrawalFee = withdrawalFeeBasisPoints;
    // NB: Return fields
    _reservationId = ++collateralReservationNonce;

    collateralReservations[_reservationId] = CollateralReservation(
        _reservingContract,
        _accountAddress,
        _tokenAddress,
        withdrawalFee,
        _reservedCollateral,
        _claimableCollateral
    );

    emit CollateralReserved(
        _reservationId,
        _accountAddress,
        _reservingContract,
        _tokenAddress,
        _reservedCollateral,
        _claimableCollateral,
        withdrawalFee
    );
}

function _transferCollateral(
    address _tokenAddress,
    address _fromAddress,
    uint256 _amount,
    address _destinationAddress
) private {
    if (_amount == 0 || _fromAddress == _destinationAddress) {
        // NB: 0 amounts should not revert, as transferCollateral may be used by pool contracts to do the reverse of
        // poolCollateral(...). If those contracts do not check for 0, reverting here may cause them to deadlock.
        return;
    }

    CollateralBalance storage fromStorage = accountBalances[_fromAddress][_tokenAddress];
    uint256 fromAvailable = fromStorage.available;
    if (_amount > fromAvailable) {
        revert InsufficientCollateral(_amount, fromAvailable);
    }

    accountBalances[_destinationAddress][_tokenAddress].available += _amount;
    fromStorage.available = fromAvailable - _amount;

    emit CollateralTransferred(_fromAddress, _tokenAddress, _destinationAddress, _amount);

function _verifyDepositApprovalSignature(
    address _accountAddress,
    address _tokenAddress,
    uint256 _amount,
    bytes memory _signature
) internal virtual {
    bytes32 hash = _hashTypedDataV4(
        keccak256(
            abi.encode(
                COLLATERALIZABLE_DEPOSIT_APPROVAL_TYPEHASH,
                msg.sender,
                _tokenAddress,
                _amount,
                _useNonce(_accountAddress, COLLATERALIZABLE_DEPOSIT_APPROVAL_TYPEHASH)
            )
        )
    );
    if (!SignatureChecker.isValidSignatureNow(_accountAddress, hash, _signature)) {
        revert InvalidSignature(_accountAddress);
    }
}

